WITH with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM transactions), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN session_start_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS session_start_flag_tier, DATE_TRUNC('WEEK', txn_time) AS week_start, DATE_TRUNC('QUARTER', txn_time) AS quarter_start, PERCENTILE_APPROX(island_id, ARRAY(0.25, 0.5, 0.75)) AS island_id_quartiles, MIN(txn_time) AS started_at FROM sessionized GROUP BY session_start_flag_tier, week_start, quarter_start ORDER BY session_start_flag_tier NULLS LAST
